import { forwardRef, type SVGProps } from "react";
import { ICON_PATHS, type IconName } from "./icons.js";
export type LucideProps = SVGProps<SVGSVGElement> & { size?: number | string; absoluteStrokeWidth?: boolean };
function glyph(name: IconName, displayName: string) {
 const Component = forwardRef<SVGSVGElement, LucideProps>(({size=24,strokeWidth=1.5,absoluteStrokeWidth: _absolute, ...props},ref)=>(
  <svg ref={ref} width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false" {...props}>
   {ICON_PATHS[name].map((d,i)=><path key={i} d={d}/>)}
  </svg>
 ));
 Component.displayName=displayName;
 return Component;
}
